/**
 * The JSON body of an action: `values` without the properties that are `undefined`, so a
 * parameter that was left out isn't sent (#96).
 */
export function requestBody(values: Record<string, unknown>): Record<string, unknown> {
  const body: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(values)) {
    if (value !== undefined) body[key] = value;
  }
  return body;
}
